def check_shared_vpc_agent(principal_from_audit,expected_service_agent,service_project_number,host_project_id,subnet,bindings):
    if not all(isinstance(x,str) and x for x in (principal_from_audit,expected_service_agent,service_project_number,host_project_id,subnet)):
